@Composable
fun OnboardingScreen(initialProfile:UserProfile,onSaveProfile:(UserProfile)->Unit,onBaseline:()->Unit,onSkip:()->Unit){
 var step by remember{mutableIntStateOf(0)};var targetWpm by remember{mutableIntStateOf(initialProfile.targetWpm)};var targetAccuracy by remember{mutableIntStateOf(initialProfile.targetAccuracy)};var dailyMinutes by remember{mutableIntStateOf(initialProfile.dailyGoalMinutes)};var focus by remember{mutableStateOf(initialProfile.focus)};val total=5
 Column(Modifier.fillMaxSize().padding(horizontal=24.dp,vertical=18.dp)){Spacer(Modifier.height(14.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Surface(shape=RoundedCornerShape(14.dp),color=MaterialTheme.colorScheme.primary.copy(.10f)){Row(Modifier.padding(horizontal=12.dp,vertical=8.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.PhoneAndroid,null,Modifier.size(18.dp),tint=MaterialTheme.colorScheme.primary);Spacer(Modifier.width(7.dp));Text("ThumbType",fontWeight=FontWeight.Black,color=MaterialTheme.colorScheme.primary)}};Text("${step+1}/$total",fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.onSurfaceVariant)};Spacer(Modifier.height(18.dp));LinearProgressIndicator(progress={(step+1)/total.toFloat()},Modifier.fillMaxWidth().height(7.dp),trackColor=MaterialTheme.colorScheme.surfaceVariant);Spacer(Modifier.height(34.dp));AnimatedContent(step,label="onboarding"){p->when(p){0->Intro();1->Goal(targetWpm,targetAccuracy,{targetWpm=it},{targetAccuracy=it});2->Focus(focus){focus=it};3->Daily(dailyMinutes){dailyMinutes=it};else->Baseline(targetWpm,targetAccuracy,dailyMinutes,focus)}};Spacer(Modifier.weight(1f));if(step<total-1){Button(onClick={step++},Modifier.fillMaxWidth().height(56.dp),shape=RoundedCornerShape(18.dp)){Text(if(step==0)"Build my training plan" else "Continue",fontWeight=FontWeight.Bold)};if(step>0)TextButton(onClick={step--},Modifier.fillMaxWidth()){Text("Back")}}else{Button(onClick={onSaveProfile(UserProfile(targetWpm,targetAccuracy,dailyMinutes,focus));onBaseline()},Modifier.fillMaxWidth().height(56.dp),shape=RoundedCornerShape(18.dp)){Icon(Icons.Default.Timer,null);Spacer(Modifier.width(7.dp));Text("Take baseline test",fontWeight=FontWeight.Bold)};TextButton(onClick={onSaveProfile(UserProfile(targetWpm,targetAccuracy,dailyMinutes,focus));onSkip()},Modifier.fillMaxWidth()){Text("Skip test for now")}}}
}
@Composable private fun Intro(){Column{Surface(shape=RoundedCornerShape(26.dp),color=MaterialTheme.colorScheme.primary.copy(.11f)){Icon(Icons.Default.TouchApp,null,Modifier.padding(20.dp).size(48.dp),tint=MaterialTheme.colorScheme.primary)};Spacer(Modifier.height(28.dp));Text("Master phone typing, not desktop typing.",style=MaterialTheme.typography.headlineLarge);Spacer(Modifier.height(14.dp));Text("ThumbType trains two-thumb reach, adaptive center keys, rhythm, accuracy and real mobile writing with a keyboard built for practice.",style=MaterialTheme.typography.bodyLarge,color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(24.dp));listOf(Icons.Default.TouchApp to "Live reach coaching",Icons.Default.AutoGraph to "Weak-key and transition analysis",Icons.Default.Security to "Offline-first and privacy-focused").forEach{(i,t)->Row(Modifier.padding(vertical=7.dp),verticalAlignment=Alignment.CenterVertically){Surface(shape=CircleShape,color=MaterialTheme.colorScheme.secondary.copy(.12f)){Icon(i,null,Modifier.padding(8.dp).size(18.dp),tint=MaterialTheme.colorScheme.secondary)};Spacer(Modifier.width(12.dp));Text(t,fontWeight=FontWeight.SemiBold)}}}}
@Composable private fun Goal(wpm:Int,accuracy:Int,onWpm:(Int)->Unit,onAccuracy:(Int)->Unit){Column{Text("Set your target",style=MaterialTheme.typography.headlineLarge);Spacer(Modifier.height(10.dp));Text("Your training score uses this target so progress stays personal.",color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(30.dp));Text("Target speed",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(10.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf(30,40,50,60).forEach{v->ChoiceChip("$v WPM",wpm==v){onWpm(v)}}};Spacer(Modifier.height(28.dp));Text("Target accuracy",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(10.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf(95,97,98,99).forEach{v->ChoiceChip("$v%",accuracy==v){onAccuracy(v)}}}}}
@Composable private fun Focus(focus:TrainingFocus,onFocus:(TrainingFocus)->Unit){Column{Text("What should improve first?",style=MaterialTheme.typography.headlineLarge);Spacer(Modifier.height(10.dp));Text("This changes the emphasis of recommendations, not what you are allowed to practice.",color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(24.dp));val o=listOf(Triple(TrainingFocus.BALANCED,Icons.Default.Tune,"Balanced") to "Speed + accuracy + rhythm",Triple(TrainingFocus.SPEED,Icons.Default.Bolt,"Speed") to "Reduce hesitation safely",Triple(TrainingFocus.ACCURACY,Icons.Default.GpsFixed,"Accuracy") to "Precision before pace",Triple(TrainingFocus.RHYTHM,Icons.Default.GraphicEq,"Rhythm") to "Even key-to-key timing");o.forEach{(m,s)->val selected=focus==m.first;Surface(Modifier.fillMaxWidth().padding(vertical=5.dp).clickable{onFocus(m.first)},shape=RoundedCornerShape(20.dp),color=if(selected)MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surface){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Icon(m.second,null,tint=if(selected)MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.width(14.dp));Column(Modifier.weight(1f)){Text(m.third,fontWeight=FontWeight.Bold);Text(s,style=MaterialTheme.typography.bodyMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)};if(selected)Icon(Icons.Default.CheckCircle,null,tint=MaterialTheme.colorScheme.primary)}}}}}
@Composable private fun Daily(minutes:Int,onMinutes:(Int)->Unit){Column{Text("Choose a sustainable daily goal",style=MaterialTheme.typography.headlineLarge);Spacer(Modifier.height(10.dp));Text("Short daily practice is more useful than occasional long sessions.",color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(28.dp));listOf(5,10,15,20).forEach{v->val selected=minutes==v;Surface(Modifier.fillMaxWidth().padding(vertical=6.dp).clickable{onMinutes(v)},shape=RoundedCornerShape(20.dp),color=if(selected)MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surface){Row(Modifier.padding(18.dp),verticalAlignment=Alignment.CenterVertically){Text("$v",style=MaterialTheme.typography.headlineLarge,color=MaterialTheme.colorScheme.primary);Spacer(Modifier.width(8.dp));Text("minutes / day",fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));if(selected)Icon(Icons.Default.CheckCircle,null,tint=MaterialTheme.colorScheme.primary)}}}}}
@Composable private fun Baseline(wpm:Int,accuracy:Int,minutes:Int,focus:TrainingFocus){Column{Text("Your plan is ready",style=MaterialTheme.typography.headlineLarge);Spacer(Modifier.height(10.dp));Text("A short baseline test lets ThumbType measure where to start.",color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(26.dp));PremiumCard{DetailLine("Speed goal","$wpm WPM");DetailLine("Accuracy goal","$accuracy%");DetailLine("Daily training","$minutes min");DetailLine("Primary focus",focus.name.lowercase().replaceFirstChar{it.uppercase()})};Spacer(Modifier.height(16.dp));Surface(shape=RoundedCornerShape(18.dp),color=MaterialTheme.colorScheme.secondaryContainer){Row(Modifier.padding(16.dp)){Icon(Icons.Default.Info,null,tint=MaterialTheme.colorScheme.secondary);Spacer(Modifier.width(12.dp));Text("The baseline uses ThumbType's training keyboard. Your personal messages are not needed and are not collected.",style=MaterialTheme.typography.bodyMedium)}}}}
@Composable private fun ChoiceChip(text:String,selected:Boolean,onClick:()->Unit){FilterChip(selected=selected,onClick=onClick,label={Text(text,fontWeight=FontWeight.Bold)},leadingIcon=if(selected){{Icon(Icons.Default.Check,null,Modifier.size(16.dp))}}else null)}

@Composable
fun HomeScreen(data:HomeUiData,onStart:(Lesson)->Unit,onNavigate:(AppScreen)->Unit){val profile=data.profile;val completed=data.completedLessonIds;val next=LessonRepository.nextLesson(completed);val workout=data.workout;val today=data.todaySeconds/60f;val goal=(today/profile.dailyGoalMinutes.coerceAtLeast(1)).coerceIn(0f,1f);val score=data.thumbScore;val hour=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);val greeting=when(hour){in 5..11->"Good morning";in 12..16->"Good afternoon";else->"Good evening"};val challenge=LessonRepository.dailyChallenge(Calendar.getInstance().get(Calendar.DAY_OF_YEAR));LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){item{AppPageHeader(greeting,"Your next session is built around efficient two-thumb movement."){TinyPill("${data.streak} day",Icons.Default.LocalFireDepartment,ThumbAmber)}};item{GradientHero("Your skill",if(score==0)"Build your baseline" else "ThumbScore $score",if(score==0)"Complete a session to establish your skill score." else skillLabel(score)){Surface(Modifier.align(Alignment.CenterEnd).size(74.dp),shape=CircleShape,color=Color.White.copy(.16f)){Box(contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally){Text(if(score==0)"—" else "${score/10}%",fontWeight=FontWeight.Black,color=Color.White);Text("skill",color=Color.White.copy(.8f),style=MaterialTheme.typography.labelMedium)}}}}};item{Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){MetricCard("${data.lastWpm}","Current WPM",Icons.Default.Speed,Modifier.weight(1f));MetricCard("${data.lastAccuracy}%","Accuracy",Icons.Default.GpsFixed,Modifier.weight(1f),MaterialTheme.colorScheme.secondary);MetricCard("${data.bestWpm}","Best WPM",Icons.Default.EmojiEvents,Modifier.weight(1f),ThumbAmber)}};item{PremiumCard{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("Daily goal",style=MaterialTheme.typography.titleMedium);Text("${today.toInt()} of ${profile.dailyGoalMinutes} minutes",color=MaterialTheme.colorScheme.onSurfaceVariant)};TinyPill(if(goal>=1f)"Complete" else "${(goal*100).toInt()}%",Icons.Default.Timer,MaterialTheme.colorScheme.secondary)};Spacer(Modifier.height(12.dp));LinearProgressIndicator(progress={goal},Modifier.fillMaxWidth().height(8.dp),trackColor=MaterialTheme.colorScheme.surfaceVariant)}};item{SectionHeading("Continue learning","View path"){onNavigate(AppScreen.Learn)}};item{PremiumCard(onClick={onStart(next)}){Row(verticalAlignment=Alignment.CenterVertically){Surface(shape=RoundedCornerShape(16.dp),color=MaterialTheme.colorScheme.primary.copy(.10f)){Icon(Icons.Default.PlayArrow,null,Modifier.padding(12.dp),tint=MaterialTheme.colorScheme.primary)};Spacer(Modifier.width(14.dp));Column(Modifier.weight(1f)){Text("Lesson ${next.id} • ${next.skill}",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.primary);Text(next.title,style=MaterialTheme.typography.titleLarge);Text(next.subtitle,color=MaterialTheme.colorScheme.onSurfaceVariant)};Icon(Icons.Default.ChevronRight,null)}}};item{SectionHeading("Today's workout")};items(workout){w->ActionRow(w.title,"${w.minutes} min • ${w.subtitle}",when(w.title){"Warm-up"->Icons.Default.Whatshot;"Weakness trainer"->Icons.Default.AutoFixHigh;"Rhythm"->Icons.Default.GraphicEq;else->Icons.Default.Bolt}){onStart(w.lesson)}};item{SectionHeading("Daily challenge")};item{PremiumCard(onClick={onStart(challenge)}){Row(verticalAlignment=Alignment.CenterVertically){Surface(shape=CircleShape,color=ThumbAmber.copy(.14f)){Icon(Icons.Default.MilitaryTech,null,Modifier.padding(12.dp),tint=ThumbAmber)};Spacer(Modifier.width(14.dp));Column(Modifier.weight(1f)){Text(challenge.title,fontWeight=FontWeight.Bold);Text("60 seconds • +${challenge.xp} XP",color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.bodyMedium)};Icon(Icons.Default.ArrowForward,null)}}};item{Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){MetricCard("${data.xp}","XP",Icons.Default.Stars,Modifier.weight(1f),ThumbAmber);MetricCard("${data.totalCharacters}","Characters",Icons.Default.Keyboard,Modifier.weight(1f),MaterialTheme.colorScheme.secondary)}}}}
private fun skillLabel(score:Int)=when{score>=900->"Elite control — train harder material, not reckless speed.";score>=800->"Advanced — strong speed, accuracy and technique.";score>=650->"Skilled — build consistency and weak transitions.";score>=450->"Developing — foundations are becoming reliable.";else->"Foundation — accuracy and rhythm come first."}

@Composable
fun LearnScreen(data:LearnUiData,onStart:(Lesson)->Unit){val completed=data.completedLessonIds;val first=LessonRepository.lessons.firstOrNull{it.id !in completed}?.id?:Int.MAX_VALUE;LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{AppPageHeader("Learning path","36 focused lessons from two-thumb foundations to advanced mobile speed.")};LessonRepository.lessons.groupBy{it.stage}.forEach{(stage,lessons)->item{Spacer(Modifier.height(8.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text("Stage $stage • ${LessonRepository.stageNames[stage]}",style=MaterialTheme.typography.titleLarge);TinyPill("${lessons.count{it.id in completed}}/${lessons.size}")}};items(lessons){lesson->val done=lesson.id in completed;val unlocked=lesson.id<=first;Surface(Modifier.fillMaxWidth().clickable(enabled=unlocked){onStart(lesson)},shape=RoundedCornerShape(20.dp),color=if(done)MaterialTheme.colorScheme.secondary.copy(.06f) else MaterialTheme.colorScheme.surface){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Surface(shape=CircleShape,color=when{done->MaterialTheme.colorScheme.secondary.copy(.14f);unlocked->MaterialTheme.colorScheme.primary.copy(.11f);else->MaterialTheme.colorScheme.surfaceVariant}){Icon(when{done->Icons.Default.Check;unlocked->Icons.Default.PlayArrow;else->Icons.Default.Lock},null,Modifier.padding(11.dp),tint=when{done->MaterialTheme.colorScheme.secondary;unlocked->MaterialTheme.colorScheme.primary;else->MaterialTheme.colorScheme.onSurfaceVariant})};Spacer(Modifier.width(13.dp));Column(Modifier.weight(1f)){Text("${lesson.id}. ${lesson.title}",fontWeight=FontWeight.Bold);Text(lesson.subtitle,style=MaterialTheme.typography.bodyMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)};Column(horizontalAlignment=Alignment.End){Text("+${lesson.xp}",fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.primary);Text("XP",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}}};item{Spacer(Modifier.height(8.dp))}}}

@Composable
fun PracticeScreen(data:PracticeUiData,onStart:(Lesson)->Unit){var custom by remember{mutableStateOf("")};val weak=data.weakDrill;LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{AppPageHeader("Practice lab","Choose a focused mode or type material that matches real phone use.")};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){TinyPill("Speed",Icons.Default.Bolt);TinyPill("Accuracy",Icons.Default.GpsFixed,MaterialTheme.colorScheme.secondary);TinyPill("Rhythm",Icons.Default.GraphicEq,ThumbAmber)}};items(LessonRepository.practiceModes){mode->val text=if(mode.name=="Weakness Trainer")weak else mode.text;val icon:ImageVector=when{mode.name.contains("Sprint")||mode.name.contains("Speed")->Icons.Default.Bolt;mode.name.contains("Benchmark")->Icons.Default.Timer;mode.name.contains("Endurance")->Icons.Default.FitnessCenter;mode.name.contains("Accuracy")->Icons.Default.GpsFixed;mode.name.contains("Rhythm")->Icons.Default.GraphicEq;mode.name.contains("Weakness")->Icons.Default.AutoFixHigh;mode.name.contains("Chat")->Icons.Default.Chat;mode.name.contains("Work")->Icons.Default.Work;mode.name.contains("Numbers")->Icons.Default.Pin;mode.name.contains("URLs")->Icons.Default.Language;else->Icons.Default.Edit};ActionRow(mode.name,mode.subtitle,icon,badge=mode.timeLimitSeconds?.let{"${it}s"}){onStart(Lesson(-100-kotlin.math.abs(mode.name.hashCode()%1000),0,mode.name,mode.subtitle,text,mode.skill,30,mode.timeLimitSeconds,true))}};item{SectionHeading("Custom practice")};item{PremiumCard{Text("Paste your own training text",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(6.dp));Text("This text is used only for the current session and is not saved in your progress data.",style=MaterialTheme.typography.bodyMedium,color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(12.dp));OutlinedTextField(value=custom,onValueChange={if(it.length<=500)custom=it},Modifier.fillMaxWidth(),minLines=3,maxLines=6,placeholder={Text("Paste a message, paragraph or vocabulary here…")},supportingText={Text("${custom.length}/500")});Spacer(Modifier.height(10.dp));Button(onClick={onStart(Lesson(-500,0,"Custom Practice","Your temporary text",custom.trim(),"Custom",20,isPractice=true))},enabled=custom.trim().length>=10,modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp)){Icon(Icons.Default.PlayArrow,null);Spacer(Modifier.width(7.dp));Text("Start custom practice")}}};item{Spacer(Modifier.height(8.dp))}}}
